package de.fit.framework.persistence.entity;
import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="position") public class PositionEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private int number;private LocalDate serviceFrom,serviceTo;@ManyToOne(fetch=FetchType.LAZY)private HilfsmittelCaseEntity root;@OneToMany(mappedBy="position",cascade=CascadeType.ALL)private final List<TerminEntity> appointments=new ArrayList<>();protected PositionEntity(){}public PositionEntity(int n,LocalDate f,LocalDate t){number=n;serviceFrom=f;serviceTo=t;}void attach(HilfsmittelCaseEntity r){root=r;}public void add(TerminEntity t){appointments.add(t);t.attach(this);}public int getNumber(){return number;}public LocalDate getServiceFrom(){return serviceFrom;}public LocalDate getServiceTo(){return serviceTo;}public List<TerminEntity> getAppointments(){return appointments;}}
